const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img = (name, alt, cls = '', eager = false) => `<img src="${A}${name}.webp" alt="${alt}" class="${cls}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'}>`;
const link = (p, label, cls='') => `<a href="${p}.html" class="${cls}" ${page===p?'aria-current="page"':''}>${label}</a>`;
