const header = () => `<div class="utility"><div class="wrap"><span>Room to discover. Space to become.</span><div class="utility-links">${link('calendar','2026–27 calendar')}${link('contact','Plan a visit')}${link('portal','Family portal ↗')}</div></div></div><header class="header"><div class="wrap nav"><a class="brand" href="index.html" aria-label="${brand} home">${logo}</a><button class="menu-button" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation">☰</button><nav class="nav-links" id="navigation" aria-label="Main navigation">${primaryNav.map(([p,l])=>link(p,l)).join('')}${buttonLink('admissions','Enquire now')}</nav></div></header><nav class="subnav" aria-label="Explore school"><div class="wrap">${moreNav.map(([p,l])=>link(p,l)).join('')}</div></nav>`;
const footer = () => `<section class="cta section sm"><div class="wrap"><div><span class="eyebrow" style="color:var(--gold)">Your next chapter</span><h2>Come curious. Leave inspired.</h2><p>The best way to know our school is to experience it.</p></div><div class="actions">${buttonLink('contact','Book a campus visit','light')}${buttonLink('admissions','Explore admissions','white')}</div></div></section><footer class="footer"><div class="wrap"><div class="grid"><div><a class="brand" href="index.html">${logo}</a><p>A thoughtful education. A connected community.<br>A place to become everything you can be.</p><span class="pill gold">Admissions open · 2027–28</span></div><div><h4>Discover</h4>${[['about','Our story'],['academics','Learning pathways'],['campus','Our campus'],['student-life','Life at '+short],['community','Our community']].map(x=>link(...x)).join('')}</div><div><h4>For families</h4>${[['admissions','Admissions'],['notices','Notice board'],['calendar','Academic calendar'],['resources','Resource centre'],['portal','Family portal']].map(x=>link(...x)).join('')}</div><div><h4>Let’s connect</h4>${[['contact','Visit our school'],['transport','School transport'],['wellbeing','Student support'],['gallery','School in pictures']].map(x=>link(...x)).join('')}<p>Mon–Fri · 8:00 am–4:00 pm<br>${schoolArea}, Varanasi<br>Uttar Pradesh, India · Sample location</p><a href="${directionsUrl}" target="_blank" rel="noopener noreferrer">Get directions ↗</a><p></p></div></div><div class="footer-bottom"><span>© 2026 ${brand}. All rights reserved.</span><span>Fictional school · UI demonstration · Illustrative images</span><button id="motion-toggle" type="button" aria-pressed="false">Motion: on</button></div></div></footer>`;
const intro = (tag,title,desc) => `<section class="page-intro"><div class="wrap"><div class="crumb">${link('index','Home')}<span>/</span>${tag}</div><span class="eyebrow">${tag}</span><h1>${title}</h1><p class="lead">${desc}</p></div></section>`;
const heading = (tag,title,aside='') => `<div class="section-heading"><div><span class="eyebrow">${tag}</span><h2>${title}</h2></div>${aside}</div>`;
const stats = () => `<div class="stats"><div class="stat"><strong>1,200+</strong><span>curious young minds</span></div><div class="stat"><strong>18:1</strong><span>student–teacher ratio</span></div><div class="stat"><strong>30+</strong><span>clubs & experiences</span></div><div class="stat"><strong>25</strong><span>years of growing together</span></div></div>`;
const programCards = () => `<div class="grid three">${[['01','Early Years','A world of wonderful firsts.','Ages 3–6 · Nursery–KG','Play, wonder and meaningful connections build the foundations for a lifelong love of learning.'],['02','Primary School','Curiosity finds its direction.','Ages 6–11 · Grades 1–5','An inquiry-led journey through language, numbers, science and the creative arts.'],['03','Middle & Senior School','Ready for a world of possibility.','Ages 11–18 · Grades 6–12','Depth of knowledge, independent thinking and real-world experiences for the journey ahead.']].map(([n,t,s,a,d])=>`<article class="card program-card tilt"><div class="card-body"><div class="number">${n} /</div><span class="card-label">${a}</span><h3>${t}</h3><p><strong>${s}</strong><br>${d}</p>${link('academics','Explore the programme '+arrow,'text-link')}</div></article>`).join('')}</div>`;
const miniNotices = () => notices.slice(0,3).map(n=>`<button class="mini-notice" data-notice="${n.id}" style="background:none;border-left:0;border-right:0;border-top:0;text-align:left;width:100%;color:inherit"><small>${n.cat.toUpperCase()} · ${n.day} SEP 2026</small>${n.title}</button>`).join('');
function homeNorth(){return `<section class="hero">${img('campus-north','Historic campus building surrounded by green trees','',true)}<div class="hero-seal">A world of<br>possibility<br>✦</div><div class="hero-content reveal"><span class="eyebrow">Welcome to ${brand}</span><h1>Great futures begin<br>with <em>curious minds.</em></h1><p>A place to ask bigger questions, discover your strengths, and grow into the person you’re meant to be.</p><div class="actions">${buttonLink('admissions','Begin your journey','light')}${buttonLink('campus','Explore our campus','outline')}</div></div><div class="hero-meta"><span>Early Years to Grade 12 · Varanasi, India</span><span>Discover what makes us different ↓</span><span>Learning. Character. Possibility.</span></div></section><div class="wrap">${stats()}</div><section class="section"><div class="wrap">${heading('Learning at Northford','A pathway for every possibility.',`<p>Every stage is a new beginning. Our learning journeys grow with your child, one discovery at a time.</p>`)}${programCards()}</div></section><section class="section soft-section"><div class="wrap">${heading('Our campus','A world within your reach.',link('campus','Explore the interactive campus '+arrow,'text-link'))}<div class="grid three">${[['heritage','01 / A place to belong','The Heritage Block','Rooted in values. Open to possibility.'],['innovation','02 / A place to discover','The Innovation Centre','Where ideas become something real.'],['outdoors','03 / A place to grow','Beyond the classroom','An education with room to breathe.']].map(([i,e,t,d])=>`<a class="image-tile" href="campus.html">${img(i,t)}<div class="tile-caption"><span class="eyebrow">${e}</span><h3>${t}</h3><p>${d}</p></div></a>`).join('')}</div></div></section><section class="section"><div class="wrap">${heading('More than classrooms','Spaces that bring learning to life.',link('campus','See all facilities '+arrow,'text-link'))}<div class="grid three">${[['library','The Learning Commons','A quiet discovery. A lively conversation. A book that changes everything.'],['sport','Play with purpose','Building confidence, resilience and friendships that last beyond the game.'],['dining','Gather. Share. Connect.','Thoughtfully prepared meals and shared moments that make a community.']].map(([i,t,d])=>`<article class="card">${img(i,t,'card-image')}<div class="card-body"><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></div></section><section class="section soft-section"><div class="wrap split"><div><span class="eyebrow">The Northford experience</span><h2>Known as an individual.<br>Part of something bigger.</h2><p class="lead">A great school is more than its lessons. It is the people who believe in you, the opportunities that surprise you, and the confidence you carry into the world.</p>${buttonLink('student-life','Discover school life')}</div><div class="quote"><div class="rating" aria-label="5 out of 5 stars">★★★★★</div><blockquote>“Here, a question is always the beginning of something. My daughter has found her voice, her people, and a love of learning.”</blockquote><cite>Meera S. <span class="muted">— Parent, Grade 6 · Sample story</span></cite></div></div></section><section class="section"><div class="wrap split"><div>${heading('Around the school','Good things are happening.')}${miniNotices()}${link('notices','View all notices '+arrow,'text-link')}</div><div class="split-image">${img('projects','Students sharing their science projects')}<div class="image-note">Small ideas. Extraordinary possibilities.</div></div></div></section>`;}
function homeOak(){return `<div class="wrap oak-home"><aside class="oak-aside" aria-label="School updates"><section class="aside-block"><div class="aside-title">The notice board <span>↗</span></div><div class="aside-body">${miniNotices()}${link('notices','All announcements →','text-link')}</div></section><section class="aside-block"><div class="aside-title">Your school corner <span>✦</span></div><div class="aside-body">${[['calendar','Academic calendar'],['resources','Learning resources'],['campus','Campus & facilities'],['gallery','School in pictures'],['transport','School transport'],['portal','Parent & student portal']].map(([p,t])=>link(p,`${t} <span>↗</span>`,'corner-link')).join('')}</div></section><section class="aside-block pattern"><div class="aside-body"><span class="eyebrow">From the principal</span><div class="aside-seal">“</div><p class="aside-quote">Every child deserves to feel seen, supported, and inspired.</p><p class="small">At Oakridge, we make space for each learner’s unique story.</p><strong class="small">Dr. Ananya Rao</strong><p class="small">Principal · Oakridge Academy</p>${link('about','Meet our educators →','text-link')}</div></section><section class="aside-block"><div class="aside-body"><span class="eyebrow">Next on the calendar</span><h3>26 <small>September</small></h3><p class="small">The Discovery Fair<br>10:00 am · Innovation Centre</p>${link('calendar','Plan your month →','text-link')}</div></section></aside><div class="oak-main"><section class="hero oak-hero">${img('classroom','Children learning together in a bright classroom','',true)}<div class="hero-content reveal"><span class="eyebrow">Welcome to Oakridge Academy</span><h1>A place to learn.<br>A space to <em>become.</em></h1><p>Nurturing curious minds and confident hearts, from their very first step to the world beyond school.</p><div class="actions">${buttonLink('admissions','Discover Oakridge','light')}</div></div></section>${stats()}${heading('Our facilities','A thoughtful space for every pursuit.',link('campus','3D campus ↗','text-link'))}${facilities.map(([i,t,e,d])=>`<article class="facility-row"><div><span class="eyebrow">${e}</span><h3>${t}</h3><p>${d}</p>${link('campus','Take a closer look ↗','text-link')}</div>${img(i,e)}</article>`).join('')}</div></div><section class="section soft-section"><div class="wrap">${heading('An education that grows with you','Small beginnings. Endless possibilities.')}${programCards()}</div></section>`;}
function about(){return intro('Our school','A school with heart.<br>An education with purpose.','We believe every child carries something extraordinary. Our role is to help them find it.')+`<section class="section"><div class="wrap split"><div class="split-image">${img(oak?'classroom':'heritage','A welcoming school environment')}<div class="image-note">Growing together since 2001</div></div><div><span class="eyebrow">The ${short} story</span><h2>Rooted in care.<br>Looking ahead.</h2><p>Our story began with a simple belief: children learn best when they feel they belong. That idea continues to guide every classroom, conversation and experience at ${short}.</p><p>We combine strong academic foundations with creativity, service and self-discovery. Students learn to think independently, care for others and find meaningful ways to contribute.</p><ul class="check-list"><li>Every learner known and supported</li><li>Inquiry, imagination and academic depth</li><li>A partnership between home and school</li></ul></div></div></section><section class="section soft-section"><div class="wrap">${heading('What we stand for','Values lived every day.')}<div class="grid four">${[['01','Curiosity','Ask why. Try something new. Find joy in discovery.'],['02','Integrity','Do what is right, even when nobody is watching.'],['03','Compassion','Listen deeply. Include others. Lead with kindness.'],['04','Courage','Have a go. Learn from mistakes. Grow with every challenge.']].map(([n,t,d])=>`<article class="card"><div class="card-body"><span class="number">${n}</span><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></div></section><section class="section"><div class="wrap">${heading('People who make the difference','Educators. Mentors. Believers.', '<p>Meet the sample leadership team behind our learning community.</p>')}<div class="grid three">${[['AR','Dr. Ananya Rao','Principal','A champion of child-centred learning and a culture of belonging.'],['VK','Vikram Kapoor','Head of Academics','Bringing inquiry, interdisciplinary learning and thoughtful assessment together.'],['MS','Maya Sen','Head of Student Wellbeing','Helping every learner develop confidence, connection and emotional resilience.']].map(([a,n,t,d])=>`<article class="card"><div class="staff-monogram" aria-hidden="true">${a}</div><div class="card-body"><span class="card-label">${t}</span><h3>${n}</h3><p>${d}</p></div></article>`).join('')}</div></div></section>`;}
const stageData = [
 {name:'Early Years',age:'Ages 3–6 · Nursery to Kindergarten',title:'Little discoveries.<br>A lifelong love of learning.',image:'early',text:'A caring, play-rich environment where children feel safe to explore, express themselves and make their first friendships.',subjects:['Language & storytelling','Numbers through play','Creative expression','Movement & sensory learning','Nature & discovery','Personal & social growth'],day:[['8:15','Welcome & circle time'],['9:00','Learning through play'],['10:15','Snack & outdoor exploration'],['11:30','Stories, reflection & home time']]},
 {name:'Primary',age:'Ages 6–11 · Grades 1–5',title:'Big questions.<br>Strong foundations.',image:'classroom',text:'An engaging balance of core skills and inquiry helps learners make connections, communicate with confidence and develop a sense of ownership.',subjects:['English & languages','Mathematical thinking','Integrated science','Social understanding','Arts & design','Physical education'],day:[['8:00','Morning connection'],['8:30','Core learning & inquiry'],['11:00','Arts, reading & languages'],['1:30','Clubs, movement & reflection']]},
 {name:'Middle School',age:'Ages 11–14 · Grades 6–8',title:'Finding their strengths.<br>Building their voice.',image:'projects',text:'An exploratory programme combines subject depth, hands-on projects and mentoring through the important middle school years.',subjects:['Mathematics & sciences','Literature & languages','Humanities','Creative computing','Design & visual arts','Service & leadership'],day:[['8:00','Tutor group & goal setting'],['8:30','Subject learning blocks'],['11:30','Lab & project studio'],['2:00','Sports, clubs & mentorship']]},
 {name:'Senior School',age:'Ages 14–18 · Grades 9–12',title:'Purposeful choices.<br>Confident next steps.',image:'computing',text:'Personalised pathways, independent research and career guidance prepare learners for higher education and life beyond the classroom.',subjects:['Science pathway','Commerce pathway','Humanities pathway','Research & extended projects','Career & university guidance','Leadership & community service'],day:[['8:00','Mentor check-in'],['8:30','Specialist subject seminars'],['11:30','Research & laboratory work'],['2:00','Guidance, independent study & enrichment']]}
];
function academics(){return intro('Academics','Learning that opens doors.','A connected journey from first discoveries to independent thinking, designed around how children grow.')+`<section class="section"><div class="wrap"><div class="tabs" role="tablist" aria-label="Learning stages">${stageData.map((s,i)=>`<button class="chip" role="tab" aria-selected="${i===0}" aria-controls="stage-panel" id="stage-${i}" data-stage="${i}">${s.name}</button>`).join('')}</div><div id="stage-panel" role="tabpanel" aria-labelledby="stage-0" style="margin-top:40px"></div></div></section><section class="section soft-section"><div class="wrap">${heading('The way we learn','Beyond the right answer.')}<div class="grid three">${[['01','Inquiry & exploration','Meaningful questions lead to investigations, experiments and deeper understanding.'],['02','Feedback that moves learning','Regular reflection, portfolios and thoughtful feedback show progress beyond a single score.'],['03','Support at every step','Learning support, extension opportunities and individual mentoring meet students where they are.']].map(([n,t,d])=>`<article class="card"><div class="card-body"><span class="number">${n}</span><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></div></section><section class="section"><div class="wrap">${heading('Clarity for families','A few useful answers.')}<div class="accordion"><details><summary>How do you support different learning needs?</summary><p>Class teachers work with learning support specialists to adapt approaches, set individual goals and review progress with families.</p></details><details><summary>How will I know how my child is progressing?</summary><p>Term reports, learner portfolios, parent–mentor conversations and the family portal provide regular opportunities to understand progress.</p></details><details><summary>Where can I find the syllabus and reading lists?</summary><p>Visit our resource centre for sample grade-wise curriculum outlines, reading suggestions and academic guides.</p>${link('resources','Open resource centre →','text-link')}</details></div></div></section>`;}
function admissions(){return intro('Admissions','Their next chapter<br>starts with a hello.','Choosing a school is a personal journey. We’re here to make the first steps thoughtful, simple and welcoming.')+`<section class="section"><div class="wrap"><div class="grid four" style="margin-bottom:50px">${[['01','Discover','Explore our learning pathways and school life.'],['02','Connect','Tell us about your child and what matters to you.'],['03','Visit','Meet our team and experience our campus.'],['04','Join us','Begin a new chapter in a caring community.']].map(([n,t,d])=>`<div><span class="eyebrow">Step ${n}</span><h3>${t}</h3><p class="small">${d}</p></div>`).join('')}</div><div class="split" style="align-items:start"><div class="form-panel"><span class="eyebrow">Admissions 2027–28</span><h3>Let’s get to know you.</h3><p class="small">A few details are all you need to begin.</p><div class="demo-banner">Interactive enquiry preview. Details stay in this page and are not sent to a school.</div><div id="admission-form"></div></div><aside class="form-aside pattern"><span class="eyebrow">A little preparation</span><h3>Your journey, made easier.</h3><p class="small">We welcome enquiries throughout the year. Placement depends on the age group and available spaces.</p><ul><li>Previous school report, where applicable</li><li>Age confirmation and family contact details</li><li>Any learning support information you’d like to share</li></ul><hr style="border:0;border-top:1px solid var(--line);margin:30px 0"><h3>Come see for yourself.</h3><p class="small">Walk through our learning spaces, meet an educator and ask all your questions.</p>${buttonLink('contact','Plan a campus visit','outline')}<p class="contact-note">Please use sample details in this UI demonstration.</p></aside></div></div></section><section class="section soft-section"><div class="wrap">${heading('Before you begin','Good questions. Clear answers.')}<div class="accordion"><details><summary>Can we visit before applying?</summary><p>Absolutely. A campus visit is a valuable first step. Select a preferred date on the contact page to preview the booking experience.</p></details><details><summary>Are scholarships and financial assistance available?</summary><p>This template includes sample merit and need-based scholarship pathways. Final eligibility, awards and fee policies should be set by the school before launch.</p></details><details><summary>What happens after the enquiry?</summary><p>In a live school workflow, an admissions counsellor would connect with you to discuss availability and a campus interaction. This front-end preview ends with a local enquiry summary.</p></details></div></div></section>`;}
const campusData = [['classroom','The Learning Block','Bright spaces for bold questions. Flexible classrooms, collaborative studios and quiet corners support every kind of learner.','Early Years · Primary · Senior classrooms'],['science','The Innovation Centre','A place to experiment, build and think differently. Science studios, computing labs and a maker space turn curiosity into discovery.','Science labs · Creative computing · Maker studio'],['library','The Learning Commons','Read, research, reflect. Our library is a shared home for stories, independent study and new perspectives.','Library · Research hub · Reading corners'],['sport','The Sports Pavilion','Confidence grows with every attempt. Spaces for indoor games, coaching and movement complement our outdoor sports grounds.','Indoor courts · Fitness studio · Team rooms']];
function campus(){return intro('Campus & facilities','Space to imagine.<br>Room to grow.','Explore the places where everyday moments become extraordinary learning experiences.')+`<section class="section"><div class="wrap">${heading('An interactive perspective','Make yourself at home.','<p>Select a building to explore. Rotate the model for a new perspective of our illustrative campus.</p>')}<div class="campus-layout"><div><div class="campus-scene"><span class="scene-label">${short.toUpperCase()} · 3D CAMPUS EXPLORER</span><div class="campus-ground" id="campus-ground"><span class="tree" aria-hidden="true"></span><span class="tree" aria-hidden="true"></span><span class="tree" aria-hidden="true"></span><span class="tree" aria-hidden="true"></span>${campusData.map((d,i)=>`<button class="building ${i===0?'active':''}" data-building="${i}" aria-label="Explore ${d[1]}" aria-pressed="${i===0}"><span class="roof">${i+1}</span><span class="front"></span><span class="side"></span><span class="back"></span><span class="left"></span></button>`).join('')}</div><div class="scene-controls"><button id="rotate-left" aria-label="Rotate campus left">↶ Rotate</button><button id="rotate-right" aria-label="Rotate campus right">Rotate ↷</button><button id="reset-campus">Reset</button><span>Illustrative campus model</span></div></div><div class="campus-legend">${campusData.map((d,i)=>`<button class="chip ${i===0?'active':''}" data-building="${i}" aria-pressed="${i===0}">${i+1}. ${d[1].replace('The ','')}</button>`).join('')}</div></div><article class="campus-detail" id="campus-detail" aria-live="polite"></article></div></div></section><section class="section soft-section"><div class="wrap">${heading('Designed around the learner','Good spaces make a difference.')}<div class="grid three">${facilities.map(([i,t,e,d])=>`<article class="card">${img(i,e,'card-image')}<div class="card-body"><span class="card-label">${e}</span><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></div></section>`;}
function studentLife(){return intro('School life','Find your people.<br>Discover your thing.','On the stage, on the field, in the studio or out in the community: there’s a place for every passion.')+`<section class="section"><div class="wrap split"><div><span class="eyebrow">More than a school day</span><h2>The moments that<br>make us who we are.</h2><p class="lead">Learning doesn’t stop at the classroom door. Clubs, house activities and student leadership create opportunities to take a chance, work together and discover unexpected strengths.</p><ul class="check-list"><li>Weekly enrichment and club sessions</li><li>Four houses. One school spirit.</li><li>A student voice in the life of the school</li></ul></div><div class="split-image">${img('arts','Students performing on stage')}<div class="image-note">Your stage. Your story.</div></div></div></section><section class="section soft-section"><div class="wrap">${heading('The club collection','Follow a spark. Find a passion.')}<div class="toolbar"><div class="filters" id="club-filters">${['All','STEM','Arts','Sports','Service'].map((t,i)=>`<button class="chip ${!i?'active':''}" data-club-filter="${t}" aria-pressed="${!i}">${t}</button>`).join('')}</div><span class="small muted">Explore a club to preview joining</span></div><div class="grid three" id="club-grid"></div></div></section><section class="section"><div class="wrap">${heading('A community within a community','Different houses. Shared values.')}<div class="grid four">${[['Arden','Growth & perseverance','#4c7655'],['Orion','Curiosity & courage','#475f82'],['Solara','Creativity & optimism','#b6873d'],['Ember','Energy & compassion','#a95e4d']].map(([n,t,c])=>`<article class="card" style="border-top:4px solid ${c}"><div class="card-body"><h3>${n}</h3><p>${t}</p><span class="small">House activities · Mentorship · Teamwork</span></div></article>`).join('')}</div></div></section>`;}
function noticePage(){return intro('Notice board','The latest. All in one place.','Important announcements, useful updates and good things happening in our community.')+`<section class="section"><div class="wrap"><div class="toolbar"><div class="filters">${['All','Admissions','Academics','Events','Parents','Transport'].map((c,i)=>`<button class="chip ${!i?'active':''}" data-notice-filter="${c}" aria-pressed="${!i}">${c}</button>`).join('')}</div><input class="search" id="notice-search" type="search" aria-label="Search notices" placeholder="Search announcements…"></div><p class="small muted" id="notice-count" role="status"></p><div id="notice-list"></div></div></section>`;}
function calendarPage(){return intro('Academic calendar','Make room for<br>what’s coming next.','Term dates, celebrations and moments to connect. A little planning for a wonderful year.')+`<section class="section"><div class="wrap"><div class="toolbar"><div class="filters">${['All','Academics','Events','Parents','Holidays','Admissions'].map((c,i)=>`<button class="chip ${!i?'active':''}" data-event-filter="${c}" aria-pressed="${!i}">${c}</button>`).join('')}</div><button class="btn outline" id="download-calendar">Download calendar ↓</button></div><div class="calendar-layout"><div class="calendar"><div class="calendar-head"><button class="icon-button" id="prev-month" aria-label="Previous month">‹</button><h3 id="month-title" aria-live="polite"></h3><button class="icon-button" id="next-month" aria-label="Next month">›</button></div><div class="weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="days" id="calendar-days"></div><p class="small muted" style="margin:18px 0 0">● A school event · Select a date to see details</p></div><aside><div class="toolbar"><h3 id="event-heading" style="margin:0">This month</h3><button class="text-link" id="all-dates" style="background:none;border-top:0;border-left:0;border-right:0">Show month</button></div><div id="event-list" aria-live="polite"></div></aside></div><div class="demo-banner" style="margin-top:25px">Sample academic schedule for 2026–27. Dates are illustrative.</div></div></section>`;}
function gallery(){return intro('School in pictures','A thousand little moments.<br>One extraordinary journey.','A glimpse into the learning, laughter and everyday discoveries that fill our days.')+`<section class="section"><div class="wrap"><div class="toolbar"><div class="filters">${['All','Learning','Arts','Sports','Campus life'].map((t,i)=>`<button class="chip ${!i?'active':''}" data-gallery-filter="${t}" aria-pressed="${!i}">${t}</button>`).join('')}</div><span class="small muted" id="gallery-count" role="status"></span></div><div class="grid three gallery-grid" id="gallery-grid"></div></div></section>`;}
const resourcesData = [
 ['Family handbook','Families','A useful guide to school routines, communication, wellbeing and community expectations.','Welcome to '+brand+'\n\nSchool day: 8:00 am–3:00 pm. Arrive ten minutes before the first session.\nCommunication: Use the family portal for class updates. Speak to the class mentor for individual concerns.\nWellbeing: Every student has access to a trusted adult and a supportive tutor group.\nAttendance: Let the school office know about planned absences.\nCommunity: Be kind, be curious and respect one another.'],
 ['Academic year at a glance','Academics','Sample term dates, assessment windows and learning milestones.','Term II begins: 28 September 2026\nParent–mentor conversations: 10 October 2026\nWinter arts showcase: 18 December 2026\nAssessment approach: Portfolios, projects, classroom evidence and term reviews.'],
 ['Primary learning guide','Academics','An introduction to subject areas and inquiry in Grades 1–5.','Core areas: English, languages, mathematics, integrated science, social understanding, arts and physical education.\nLearning habits: Ask questions, read daily, explore patterns, explain your thinking and reflect on progress.\nFamily connection: Read together and celebrate effort.'],
 ['Reading for pleasure','Learning','Ideas to help young readers build a joyful reading habit.','Early Years: Read aloud, explore picture books and retell favourite stories.\nPrimary: Choose a mix of stories, poetry and illustrated nonfiction.\nMiddle School: Try new genres and keep a reading journal.\nSenior School: Explore essays, biographies and literature from different cultures.'],
 ['Admissions checklist','Admissions','Prepare for a conversation about your child’s next chapter.','Before your visit:\n1. Explore the learning stage for your child.\n2. Note your questions about learning, support and school life.\n3. Bring the most recent school report if applicable.\n4. Share any information that helps us understand your child.\nThis is a sample checklist; no documents should be uploaded to this template.'],
 ['Digital citizenship guide','Wellbeing','A shared approach to kind, thoughtful and responsible technology use.','Think before sharing. Protect personal information. Ask permission before posting someone else’s work or photograph. Credit sources. Balance screen time with rest, movement and face-to-face connection. Ask a trusted adult when something feels wrong.'],
 ['School transport guide','Families','Pickup routines, route planning and a comfortable daily journey.','Be ready at the assigned stop five minutes early. Use the designated pickup point. Remain seated during the journey. Treat others with respect. Share route changes with the school transport office in advance. Routes in this template are illustrative.'],
 ['Scholarship overview','Admissions','Sample pathways recognising potential, commitment and financial need.','Merit pathway: A review of sustained engagement in academics, arts, sport or service.\nNeed-based support: A confidential school-led review.\nSchool-specific eligibility, application periods, award amounts and required documents must be added before production use.'],
];
function resources(){return intro('Resource centre','A little less searching.<br>A lot more clarity.','Helpful guides, learning resources and everyday essentials for our school community.')+`<section class="section"><div class="wrap"><div class="toolbar"><div class="filters">${['All','Families','Academics','Learning','Admissions','Wellbeing'].map((t,i)=>`<button class="chip ${!i?'active':''}" data-resource-filter="${t}" aria-pressed="${!i}">${t}</button>`).join('')}</div><input type="search" class="search" id="resource-search" aria-label="Search resources" placeholder="Find a guide…"></div><div class="grid three" id="resource-grid"></div><p class="small muted" style="margin-top:25px">Downloads are accessible text guides with sample content, ready to customise for your school.</p></div></section>`;}
