function transport(){return intro('School transport','A good day starts<br>with a comfortable journey.','Thoughtfully planned routes and clear routines help families feel connected from the first pickup to the last drop-off.')+`<section class="section"><div class="wrap"><div class="toolbar"><div><label for="route-select">Explore a sample route</label><select id="route-select">${routes.map((r,i)=>`<option value="${i}">${r.name}</option>`).join('')}</select></div><span class="pill gold">Illustrative routes · No live tracking</span></div><div class="split" style="align-items:start"><div id="route-details"></div><div class="route-map" id="route-map" role="img" aria-label="Schematic school transport route"></div></div></div></section><section class="section soft-section"><div class="wrap">${heading('Care along the way','More than getting from A to B.')}<div class="grid three">${[['Thoughtful supervision','A sample transport service designed around supervised boarding, clear attendance routines and designated pickup points.'],['Predictable communication','Families can review planned departure times and route changes through school announcements.'],['A shared responsibility','Students learn to be considerate passengers. Families help by being ready at the assigned stop five minutes early.']].map(([t,d])=>`<article class="card"><div class="card-body"><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></div></section>`;}
function wellbeing(){return intro('Wellbeing & support','Feeling good.<br>Growing well.','Every student deserves a trusted adult, a sense of belonging and the confidence to ask for support.')+`<section class="section"><div class="wrap split"><div class="split-image">${img('wellness','Students taking part in a movement and mindfulness session')}</div><div><span class="eyebrow">Care is part of the curriculum</span><h2>Seen. Heard.<br>Supported.</h2><p>Wellbeing is woven into school life through regular mentor time, social and emotional learning, movement, rest and positive relationships.</p><p>Our support approach brings families, educators and students together to understand what each learner needs to thrive.</p>${buttonLink('contact','Connect with student support')}</div></div></section><section class="section soft-section"><div class="wrap">${heading('A circle of support','The right support, at the right time.')}<div class="grid three">${[['Mentoring & connection','Regular check-ins with a class mentor create a familiar space to share successes, questions and concerns.'],['Learning support','Individual strategies, collaborative planning and regular reviews help learners access the curriculum with confidence.'],['Counselling & guidance','A supportive school team offers a place to talk and helps families identify appropriate next steps.'],['Digital wellbeing','Students practise responsible online choices, respectful communication and balanced technology habits.'],['Nutrition & movement','Daily opportunities to move, play and recharge support a balanced school experience.'],['Safe & inclusive spaces','Clear expectations, a culture of kindness and accessible reporting channels help everyone feel they belong.']].map(([t,d])=>`<article class="card"><div class="card-body"><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></div></section>`;}
function community(){return intro('Our community','Once you belong,<br>you always belong.','Students, families, educators and alumni. Different journeys, connected by a shared sense of possibility.')+`<section class="section"><div class="wrap split"><div><span class="eyebrow">Better, together</span><h2>A school is made<br>by its people.</h2><p class="lead">The ${short} community extends far beyond the school gates. Families share their expertise, alumni open doors, and students learn the value of giving back.</p>${buttonLink('contact','Connect with our community')}</div>${img('council','Students working together as a school community','card-image',true)}</div></section><section class="section soft-section"><div class="wrap"><div class="grid three">${[['Family partnership','A conversation that keeps growing.','Parent workshops, mentor conversations and community events make families active partners in learning.','Parent workshops'],['Alumni network','Different paths. A shared beginning.','Alumni share experiences, support student projects and stay connected through school reunions and mentoring.','Alumni mentoring'],['Service & sustainability','Small actions. Meaningful change.','Student-led service, neighbourhood partnerships and environmental projects connect learning with responsibility.','Community volunteering']].map(([t,h,d,o])=>`<article class="card"><div class="card-body"><span class="card-label">${t}</span><h3>${h}</h3><p>${d}</p><button class="btn outline" data-interest="${o}">Get involved ↗</button></div></article>`).join('')}</div></div></section><section class="section"><div class="wrap">${heading('Voices from our community','What stays with you.')}<div class="grid two"><div class="quote"><blockquote>“The confidence to ask a question, and the courage to try. Those are the things I took with me.”</blockquote><cite>Aarav M. · Alumni story · Sample content</cite></div><div class="quote"><blockquote>“It feels like a partnership. We know our child’s teachers, and they know our child.”</blockquote><cite>Riya & Aditya · Parent story · Sample content</cite></div></div></div></section>`;}
function contact(){return intro('Visit & connect','A conversation is<br>a wonderful beginning.','Come with questions. Come with curiosity. We would love to help you get to know our school.')+`<section class="section"><div class="wrap split" style="align-items:start"><div class="form-panel"><span class="eyebrow">Let’s connect</span><h3>How can we help?</h3><p class="small">Choose a campus visit or send a general enquiry.</p><div class="demo-banner">Preview only. No message or booking is sent. Please use sample details.</div><form id="contact-form"><div class="form-grid"><div class="field"><label for="contact-name">Your name</label><input id="contact-name" name="name" required autocomplete="name" placeholder="e.g. Alex Sharma"></div><div class="field"><label for="contact-email">Email address</label><input id="contact-email" name="email" type="email" required autocomplete="email" placeholder="alex@example.com"></div></div><div class="field"><label for="contact-topic">I’d like to talk about</label><select id="contact-topic" name="topic"><option>Campus visit</option><option>Admissions</option><option>Student support</option><option>Transport</option><option>Alumni & community</option><option>General enquiry</option></select></div><div class="form-grid" id="visit-fields"><div class="field"><label for="visit-date">Preferred date</label><input type="date" id="visit-date" name="date" required min="${new Date().toLocaleDateString('en-CA')}"></div><div class="field"><label for="visit-time">Preferred time</label><select id="visit-time" name="time"><option>10:00 am</option><option>11:30 am</option><option>2:00 pm</option></select></div></div><div class="field"><label for="contact-message">Anything you’d like us to know? <span class="muted">(optional)</span></label><textarea id="contact-message" name="message" placeholder="Tell us what you’re curious about…"></textarea></div><button class="btn" type="submit">Preview enquiry ${arrow}</button></form></div><aside><span class="eyebrow">The welcome centre</span><h2>Step inside.<br>Feel the difference.</h2><p>Walk through our learning spaces, meet our people, and picture your child’s next chapter.</p><div class="card"><div class="card-body"><span class="card-label">Plan your visit</span><h3>${brand}</h3><p>${schoolArea}, Varanasi<br>Uttar Pradesh, India<br><span class="small">Sample school location</span></p><ul class="check-list"><li>Monday–Friday · 8:00 am–4:00 pm</li><li>Campus visits by appointment</li><li>Allow approximately 60 minutes</li></ul></div></div><div style="margin-top:25px">${img(oak?'classroom':'heritage','A glimpse of our school','card-image')}</div></aside></div></section>`;}
function portal(){return intro('Family portal','A closer connection<br>to every school day.','Learning, progress and the little things that matter. Together in one thoughtful space.')+`<section class="section"><div class="wrap"><div class="demo-banner">Demo portal · Fictional student records · No sign-in required · Changes last only for this visit.</div><div class="toolbar"><span class="small">Explore a portal experience</span><div class="tabs" role="tablist" aria-label="Portal role">${['Parent','Student','Teacher'].map((r,i)=>`<button class="chip" role="tab" aria-selected="${!i}" data-role="${r}">${r}</button>`).join('')}</div></div><div class="portal-layout"><aside class="portal-side"><div class="avatar">AS</div><h3 id="portal-person">Aarav Sharma</h3><p>Grade 8 · Section A · Arden House</p>${['Overview','Assignments','Attendance','Reports','Fees','Appointments'].map((x,i)=>`<button class="${!i?'active':''}" data-portal-tab="${x}" aria-pressed="${!i}">${x}</button>`).join('')}</aside><div id="portal-content" aria-live="polite"></div></div></div></section>`;}
