app.innerHTML = header()+`<main id="main">${(pages[page]||homeNorth)()}</main>`+footer()+`<dialog class="dialog" id="dialog" aria-labelledby="dialog-title"><div class="dialog-top"><span id="dialog-title">${brand}</span><button class="icon-button" id="close-dialog" aria-label="Close dialog">×</button></div><div class="dialog-content" id="dialog-content"></div></dialog><div id="toast" class="toast" role="status" hidden></div>`;
if(page==='index'){
 const studio=document.createElement('school-discovery');
 studio.setAttribute('theme','oakridge');studio.id='discovery-studio';
 document.querySelector('main .hero')?.insertAdjacentElement('afterend',studio);
}
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const on = (s,e,f) => $(s)?.addEventListener(e,f);
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
let previousFocus;
function modal(title,body){previousFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=body;$('#dialog').showModal();$('#close-dialog').focus();}
function closeModal(){$('#dialog').close();previousFocus?.focus();}
on('#close-dialog','click',closeModal);
on('#dialog','click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
on('#dialog','close',()=>previousFocus?.focus());
on('.menu-button','click',()=>{const open=$('#navigation').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',open);$('.menu-button').setAttribute('aria-label',open?'Close navigation':'Open navigation');$('.menu-button').textContent=open?'×':'☰';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#navigation').classList.contains('open')){$('#navigation').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Open navigation');$('.menu-button').textContent='☰';$('.menu-button').focus();}});
let motionOff=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{motionOff=motionOff||localStorage.getItem('school-motion')==='off';}catch{}
function applyMotion(){document.body.classList.toggle('motion-off',motionOff);$('#motion-toggle').textContent=`Motion: ${motionOff?'off':'on'}`;$('#motion-toggle').setAttribute('aria-pressed',motionOff);$$('.tilt').forEach(e=>e.style.transform='');}
applyMotion();on('#motion-toggle','click',()=>{motionOff=!motionOff;applyMotion();try{localStorage.setItem('school-motion',motionOff?'off':'on');}catch{}});
$$('.tilt').forEach(card=>{card.addEventListener('pointermove',e=>{if(motionOff||e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=card.getBoundingClientRect();card.style.transform=`perspective(900px) rotateX(${-(e.clientY-r.top-r.height/2)/70}deg) rotateY(${(e.clientX-r.left-r.width/2)/65}deg) translateY(-4px)`;});card.addEventListener('pointerleave',()=>card.style.transform='');});
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Your download is ready.');}
function selectButtons(selector,attribute,value){$$(selector).forEach(b=>{const active=b.dataset[attribute]===String(value);b.classList.toggle('active',active);b.setAttribute(b.getAttribute('role')==='tab'?'aria-selected':'aria-pressed',active);});}
document.addEventListener('click',e=>{const n=e.target.closest('[data-notice]');if(n){const d=notices.find(x=>x.id===Number(n.dataset.notice));modal(d.cat+' · '+d.day+' September 2026',`<span class="pill">${d.cat}</span><h2>${d.title}</h2><p>${d.text}</p><p class="small">For: ${d.meta}</p><div class="actions">${buttonLink(d.cat==='Admissions'?'admissions':d.cat==='Parents'?'portal':d.cat==='Transport'?'transport':d.cat==='Academics'?'resources':'calendar','Explore more')}<button class="btn outline" data-download-notice="${d.id}">Download notice ↓</button></div>`);}const nd=e.target.closest('[data-download-notice]');if(nd){const d=notices.find(n=>n.id===Number(nd.dataset.downloadNotice));download(`notice-${d.id}.txt`,`${brand}\nSample school notice · ${d.day} September 2026\n\n${d.title}\n\n${d.text}`);}const interest=e.target.closest('[data-interest]');if(interest)interestModal(interest.dataset.interest);});
function interestModal(title){modal(title,`<span class="eyebrow">Make a connection</span><h2>${title}</h2><p>Share a little about your interest to preview the next step. This is a local demo; no registration is sent.</p><form id="interest-form"><div class="field"><label for="interest-name">Your name</label><input id="interest-name" required placeholder="Sample name"></div><div class="field"><label for="interest-email">Email address</label><input id="interest-email" type="email" required placeholder="name@example.com"></div><button class="btn">Preview interest ${arrow}</button></form>`);on('#interest-form','submit',e=>{e.preventDefault();$('#dialog-content').innerHTML=`<div class="success-mark">✓</div><h2>You’ve found a new possibility.</h2><p>Your interest in <strong>${esc(title)}</strong> is ready to share. This preview has not sent any information.</p>`;});}
if(page==='academics'){
 const renderStage=i=>{const s=stageData[i];selectButtons('[data-stage]','stage',i);$('#stage-panel').setAttribute('aria-labelledby','stage-'+i);$('#stage-panel').innerHTML=`<div class="split reveal"><div><span class="eyebrow">${s.age}</span><h2>${s.title}</h2><p>${s.text}</p><ul class="check-list">${s.subjects.map(t=>`<li>${t}</li>`).join('')}</ul>${buttonLink('admissions','Explore admissions')}</div><div class="split-image">${img(s.image,s.name+' learning experience')}<div class="image-note">${s.name} · A day of discovery</div></div></div><div style="margin-top:55px"><span class="eyebrow">A typical school day</span><div class="grid four">${s.day.map(([t,d])=>`<div class="card"><div class="card-body"><span class="card-label">${t}</span><h3 style="font-size:21px">${d}</h3></div></div>`).join('')}</div></div>`;};
 $$('[data-stage]').forEach(b=>b.addEventListener('click',()=>renderStage(+b.dataset.stage)));renderStage(0);
}
if(page==='admissions'){
 let step=0;const data={};
 const form=()=>{const titles=['Your family','Your child','Review'];$('#admission-form').innerHTML=`<div class="steps">${titles.map((t,i)=>`<span class="${step===i?'active':''}" ${step===i?'aria-current="step"':''}><b>${i+1}</b>${t}</span>`).join('')}</div><form id="enquiry-step">${step===0?`<div class="field"><label for="parent-name">Parent / guardian name</label><input id="parent-name" name="parent" required value="${esc(data.parent||'')}" autocomplete="name" placeholder="e.g. Alex Sharma"></div><div class="form-grid"><div class="field"><label for="parent-email">Email address</label><input id="parent-email" name="email" type="email" required value="${esc(data.email||'')}" autocomplete="email" placeholder="alex@example.com"></div><div class="field"><label for="parent-phone">Phone number</label><input id="parent-phone" name="phone" type="tel" required pattern="[+0-9() -]{7,20}" value="${esc(data.phone||'')}" autocomplete="tel" placeholder="+91 90000 00000"></div></div>`:step===1?`<div class="field"><label for="child-name">Child’s first name</label><input id="child-name" name="child" required value="${esc(data.child||'')}" placeholder="e.g. Aarav"></div><div class="form-grid"><div class="field"><label for="grade">Applying for</label><select name="grade" id="grade" required><option value="">Choose a grade</option>${['Nursery','Kindergarten',...Array.from({length:12},(_,i)=>'Grade '+(i+1))].map(g=>`<option ${data.grade===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label for="year">Academic year</label><select name="year" id="year"><option>2027–28</option><option ${data.year==='2026–27'?'selected':''}>2026–27</option></select></div></div><div class="field"><label for="interests">What does your child enjoy? <span class="muted">(optional)</span></label><textarea id="interests" name="interests" placeholder="A favourite subject, a hobby, a big question…">${esc(data.interests||'')}</textarea></div>`:`<h3>Your enquiry, at a glance.</h3><div class="review-grid">${[['Parent / guardian',data.parent],['Email',data.email],['Phone',data.phone],['Child',data.child],['Applying for',data.grade],['Academic year',data.year],['Interests',data.interests||'Not provided']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><label class="checkbox"><input type="checkbox" required>I understand this is a UI preview and no enquiry will be sent.</label>`}<div class="actions" style="margin-top:25px">${step?'<button type="button" class="btn outline" id="step-back">← Back</button>':''}<button type="submit" class="btn">${step===2?'Create preview':'Continue'} →</button></div></form>`;on('#enquiry-step','submit',e=>{e.preventDefault();Object.assign(data,Object.fromEntries(new FormData(e.target)));if(step<2){step++;form();$('#enquiry-step input, #enquiry-step select, #enquiry-step button')?.focus();}else{$('#admission-form').innerHTML=`<div class="success-mark">✓</div><h3>A wonderful beginning, ${esc(data.parent.split(' ')[0])}.</h3><p>Your sample enquiry for ${esc(data.child)}, ${esc(data.grade)}, is ready. No information has been sent or stored.</p><div class="actions"><button class="btn" id="enquiry-download">Download summary ↓</button><button class="btn outline" id="enquiry-reset">Start again</button></div>`;on('#enquiry-download','click',()=>download('enquiry-preview.txt',`${brand}\nENQUIRY PREVIEW — NOT SUBMITTED\n\n`+Object.entries(data).map(([k,v])=>`${k}: ${v}`).join('\n')));on('#enquiry-reset','click',()=>{Object.keys(data).forEach(k=>delete data[k]);step=0;form();});}});on('#step-back','click',()=>{Object.assign(data,Object.fromEntries(new FormData($('#enquiry-step'))));step--;form();});};form();
}
