if(page==='calendar'){
 let year=2026,month=8,selected=null,filter='All';const pad=n=>String(n).padStart(2,'0');const key=d=>`${year}-${pad(month+1)}-${pad(d)}`;
 const render=()=>{const title=new Date(year,month,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'});$('#month-title').textContent=title;const start=(new Date(year,month,1).getDay()+6)%7;const length=new Date(year,month+1,0).getDate();const filtered=events.filter(e=>(filter==='All'||e.cat===filter)&&e.date.startsWith(`${year}-${pad(month+1)}`));$('#calendar-days').innerHTML=Array.from({length:start},()=>'<span class="day" aria-hidden="true"></span>').join('')+Array.from({length},(_,i)=>{const d=i+1;const ev=filtered.some(e=>e.date===key(d));return `<button class="day ${ev?'event':''} ${selected===d?'selected':''}" data-date="${d}" aria-pressed="${selected===d}" aria-label="${d} ${title}${ev?', school event':''}">${d}</button>`;}).join('');$('#event-heading').textContent=selected?`${selected} ${new Date(year,month,1).toLocaleDateString('en-GB',{month:'long'})}`:'This month';const list=filtered.filter(e=>!selected||e.date===key(selected));$('#event-list').innerHTML=list.length?list.map(e=>`<article class="event-card"><span class="pill">${e.cat} · ${new Date(e.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span><h3>${e.title}</h3><p>${e.text}</p><span class="small muted">${e.time}<br>${e.place}</span></article>`).join(''):'<div class="empty"><h3>A little breathing space.</h3><p>No scheduled events for this selection.</p></div>';$$('[data-date]').forEach(b=>b.addEventListener('click',()=>{selected=+b.dataset.date;render();$(`[data-date="${selected}"]`)?.focus();}));};on('#prev-month','click',()=>{if(--month<0){month=11;year--;}selected=null;render();});on('#next-month','click',()=>{if(++month>11){month=0;year++;}selected=null;render();});on('#all-dates','click',()=>{selected=null;render();});$$('[data-event-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.eventFilter;selectButtons('[data-event-filter]','eventFilter',filter);render();}));on('#download-calendar','click',()=>{const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//School Template//Academic Calendar//EN','CALSCALE:GREGORIAN',...events.flatMap(e=>{const end=new Date(e.date+'T12:00:00');end.setDate(end.getDate()+1);return ['BEGIN:VEVENT',`UID:${e.date}-${short}@school.example`,'DTSTAMP:20260924T000000Z',`DTSTART;VALUE=DATE:${e.date.replaceAll('-','')}`,`DTEND;VALUE=DATE:${end.toISOString().slice(0,10).replaceAll('-','')}`,`SUMMARY:${e.title}`,`LOCATION:${e.place}`,`DESCRIPTION:Sample schedule. ${e.time}. ${e.text}`,'END:VEVENT'];}),'END:VCALENDAR'];download('academic-calendar.ics',lines.join('\r\n'),'text/calendar;charset=utf-8');});render();
}
