 if(tab==='Assignments'){body=`<p class="small muted" style="margin-top:25px">${role==='Teacher'?'Review sample class assignments and preview completion status.':'Explore this week’s learning tasks. Marking a task complete updates this local preview.'}</p><div class="grid">${assignments.map(([s,t,d,status],i)=>`<article class="card"><div class="card-body"><div class="toolbar" style="margin-bottom:12px"><span class="pill">${s}</span><span class="small muted">Due ${d}</span></div><h3>${t}</h3><p>${i===0?'Create a labelled design and explain three choices that reduce environmental impact.':i===1?'Write 500 words retelling a familiar event from a different character’s point of view.':'Find and explain three mathematical patterns in your home or neighbourhood.'}</p><div class="actions"><span class="pill ${completed.has(i)?'green':'gold'}">${completed.has(i)?'Complete':status}</span><button class="btn outline" data-complete="${i}">${completed.has(i)?'Mark incomplete':'Mark complete'}</button></div></div></article>`).join('')}</div>`;}
 if(tab==='Attendance'){body=`<div class="dashboard-stats"><div class="metric"><small>Attendance rate</small><strong>96.4%</strong></div><div class="metric"><small>Days present</small><strong>27</strong></div><div class="metric"><small>Excused absence</small><strong>1</strong></div></div><h3>Recent school days</h3>${table(['Date','Status','Note'],[['24 Sep 2026','<span class="pill green">Present</span>','On time'],['23 Sep 2026','<span class="pill green">Present</span>','On time'],['22 Sep 2026','<span class="pill green">Present</span>','On time'],['21 Sep 2026','<span class="pill gold">Excused</span>','Family appointment'],['18 Sep 2026','<span class="pill green">Present</span>','On time']])}`;}
 if(tab==='Reports'){body=`<div class="card" style="margin-top:25px"><div class="card-body"><span class="card-label">Term I · Learning snapshot</span><h3>Progress beyond a score.</h3><p>A sample overview of achievement, engagement and next steps.</p>${table(['Learning area','Achievement','Teacher observation'],[['Mathematics','A','Confident reasoning; explain each step.'],['Science','A','Strong inquiry and collaboration.'],['English','B+','Expressive ideas; develop structure.'],['Humanities','A','Thoughtful connections and research.'],['Arts & design','A','Original ideas and careful reflection.']])}<button class="btn outline" style="margin-top:25px" id="report-download">Download sample report ↓</button></div></div>`;}
